<?php

namespace Database\Seeders;

use App\Enums\MerchantCategory;
use App\Models\Merchant;
use Illuminate\Database\Seeder;

/**
 * Первоначальное наполнение справочника мерчантов — самые популярные зарубежные
 * сервисы, которые российские пользователи оплачивают через виртуальные карты.
 * У части мерчантов (взятых с лендинга, раздел «Что оплатить?») уже есть проверенный
 * SVG-логотип (иконки Simple Icons, только <path>, вьюбокс 24×24). У остальных
 * logo_svg оставлен пустым — админ может добавить его позже через форму мерчанта,
 * само определение мерчанта по коду работает и без логотипа.
 *
 * code — подстрока, по которой мерчант ищется в CardTransaction::merchant. Это
 * отправная точка, а не гарантированно точный дескриптор эмитента — при появлении
 * реальных транзакций код можно скорректировать в самой карточке мерчанта.
 */
class MerchantSeeder extends Seeder
{
    public function run(): void
    {
        foreach (self::merchants() as $merchant) {
            Merchant::query()->updateOrCreate(
                ['code' => $merchant['code']],
                [
                    'name' => $merchant['name'],
                    'category' => $merchant['category'],
                    'color' => $merchant['color'],
                    'logo_svg' => $merchant['logo_svg'] ?? null,
                    'is_active' => true,
                ]
            );
        }
    }

